/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import json,collections
r=Path('.')
s=json.loads((r/'harnesses/stages.json').read_text()); print(type(s['problems'])); print(str(s['problems'])[:400]); print(json.dumps([p for p in s['problems'] if '12' in str(p.get('problem',''))],indent=1) if isinstance(s['problems'],list) else json.dumps(s['problems'].get('P12'),indent=1))
counts=collections.Counter(); patterns=collections.defaultdict(list); faults=[]; extras=collections.defaultdict(set)
for c in ['constraints','coroutines','plain','session','tabling']:
 for p in sorted((r/'results/swi-prolog'/c/'P12/raw').glob('*.json')):
  d=json.loads(p.read_text()); a=d['stages'][0]['attempts'][0]; q=a['computations'][0]; ans=q['queries'][0]
  counts[c,d['run']['mode'],','.join(q['execution_state']['states']),ans['ended_by'],len(ans['answers'])]+=1
  if d['harness_faults']: faults.append((str(p),d['harness_faults']))
  for k in ['stdout','stderr','manual_actions']: extras[k].add(str(a.get(k)))
  if d['run']['mode']=='behaviour':
   patterns[c].append((d['run']['instance'],[x['verbatim'] for x in ans['answers']],q['candidates_examined'],q['suspended'],a['observe']['raw']))
print('COUNTS',*counts.items(),sep='\\n'); print('FAULTS',faults); print('EXTRAS',dict(extras))
for c in ['plain','tabling']:
 print('PATTERNS',c)
 for row in patterns[c]: print(row)
PY"

